const results = [];

for (const item of $input.all()) {

  // ==================================================
  // 1. GET AI AGENT OUTPUT
  // ==================================================

  const rawOutput = item.json.output || "";


  // ==================================================
  // 2. CLEAN MARKDOWN CODE BLOCKS
  // ==================================================

  const jsonString = rawOutput
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();


  // ==================================================
  // 3. PARSE JSON
  // ==================================================

  let data = {};

  try {

    data = JSON.parse(jsonString);

  } catch (error) {

    results.push({
      json: {
        error: "Failed to parse JSON",
        errorMessage: error.message,
        rawOutput: rawOutput
      }
    });

    continue;
  }


  // ==================================================
  // 4. SCORE LABEL
  // ==================================================

  const getScoreLabel = (value) => {

    if (value >= 85) return "Excellent";
    if (value >= 70) return "Good";
    if (value >= 50) return "Moderate";

    return "Weak";
  };


  // ==================================================
  // 5. CONVERT SCORES OBJECT TO ARRAY
  // ==================================================

  const scores = data.scores
    ? Object.entries(data.scores).map(([key, value]) => ({

        name: key
          .split("_")
          .map(word =>
            word.charAt(0).toUpperCase() + word.slice(1)
          )
          .join(" "),

        value: Number(value),

        label: getScoreLabel(Number(value))

      }))
    : [];


  // ==================================================
  // 6. BUILD FINAL JSON
  // ==================================================

  results.push({

    json: {


      // ==================================================
      // BASIC INFORMATION
      // ==================================================

      ideaName:
        data.idea_name || "Startup Idea",

      title:
        "Idea Analysis",

      summary:
        data.summary || "",

      problem:
        data.problem || "",

      solution:
        data.solution || "",

      valueProposition:
        data.value_proposition || "",

      targetCustomer:
        data.target_customer || "",


      // ==================================================
      // OVERALL SCORES
      // ==================================================

      scores:
        scores,


      // ==================================================
      // PROBLEM VALIDATION
      // ==================================================

      problemAnalysis: {

        intensityScore:
          Number(
            data.problem_analysis?.intensity_score || 0
          ),

        frequency:
          data.problem_analysis?.frequency || "",

        urgency:
          data.problem_analysis?.urgency || "",

        currentAlternatives:
          data.problem_analysis?.current_alternatives || "",

        economicImpact:
          data.problem_analysis?.economic_impact || "",

        willingnessToPay:
          data.problem_analysis?.willingness_to_pay || "",

        isWorthSolving:
          data.problem_analysis?.is_worth_solving || "",

        reasoning:
          data.problem_analysis?.reasoning || ""
      },


      problemScore:
        Number(
          data.problem_score || 0
        ),

      isWorthSolving:
        data.is_worth_solving || "",

      problemValidationSummary:
        data.problem_validation_summary || "",


      // ==================================================
      // CUSTOMER ANALYSIS
      // ==================================================

      customerAnalysis: {

        customerProfile:
          data.customer_analysis?.customer_profile || "",

        primaryUser:
          data.customer_analysis?.primary_user || "",

        buyer:
          data.customer_analysis?.buyer || "",

        decisionMaker:
          data.customer_analysis?.decision_maker || "",

        ageRangeGender:
          data.customer_analysis?.age_range_gender || "",

        geographicScope:
          data.customer_analysis?.geographic_scope || "",

        socioeconomicProfile:
          data.customer_analysis?.socioeconomic_profile || "",

        knowledgeTechSavviness:
          data.customer_analysis?.knowledge_tech_savviness || "",

        behavioralPsychologicalProfile:
          data.customer_analysis
            ?.behavioral_psychological_profile || "",

        b2bContext:
          data.customer_analysis?.b2b_context || "",

        customerAcquisitionEase:
          data.customer_analysis
            ?.customer_acquisition_ease || ""
      },


      // ==================================================
      // CUSTOMER SIMPLIFIED FIELDS
      // ==================================================

      targetCustomerProfile:
        data.target_customer_profile || "",

      customerDemographics:
        data.customer_demographics || "",

      customerSocioeconomicProfile:
        data.customer_socioeconomic_profile || "",

      customerBehavioralProfile:
        data.customer_behavioral_profile || "",

      customerAcquisitionEase:
        data.customer_acquisition_ease || "",


      // ==================================================
      // SOLUTION EVALUATION
      // ==================================================

      solutionEvaluation: {

        problemSolutionFit:
          data.solution_evaluation
            ?.problem_solution_fit || "",

        customerValue:
          data.solution_evaluation
            ?.customer_value || "",

        differentiation:
          data.solution_evaluation
            ?.differentiation || "",

        unfairAdvantage:
          data.solution_evaluation
            ?.unfair_advantage || "",

        technicalFeasibility:
          data.solution_evaluation
            ?.technical_feasibility || "",

        operationalFeasibility:
          data.solution_evaluation
            ?.operational_feasibility || "",

        keyRisks:
          data.solution_evaluation
            ?.key_risks || "",

        executionBlockers:
          data.solution_evaluation
            ?.execution_blockers || ""
      },


      // ==================================================
      // BUSINESS ANALYSIS
      // ==================================================

      businessAnalysis: {

        monetization:
          data.business_analysis?.monetization || "",

        recurringRevenue:
          data.business_analysis?.recurring_revenue || "",

        customerAcquisition:
          data.business_analysis?.customer_acquisition || "",

        retention:
          data.business_analysis?.retention || "",

        competitivePressure:
          data.business_analysis?.competitive_pressure || "",

        unitEconomics:
          data.business_analysis?.unit_economics || "",

        expansionPotential:
          data.business_analysis?.expansion_potential || ""
      },


      // ==================================================
      // MARKET ANALYSIS
      // ==================================================

      marketAnalysis: {

        market:
          data.market_analysis?.market || "",

        marketSummary:
          data.market_analysis?.market_summary || "",

        demandSignals:
          Array.isArray(
            data.market_analysis?.demand_signals
          )
            ? data.market_analysis.demand_signals
            : [],

        growth:
          data.market_analysis?.growth || "",

        trends:
          Array.isArray(
            data.market_analysis?.trends
          )
            ? data.market_analysis.trends
            : [],

        opportunities:
          Array.isArray(
            data.market_analysis?.opportunities
          )
            ? data.market_analysis.opportunities
            : [],

        geographicOpportunities:
          Array.isArray(
            data.market_analysis?.geographic_opportunities
          )
            ? data.market_analysis.geographic_opportunities
            : [],

        industryMaturity:
          data.market_analysis?.industry_maturity || "",

        marketRisks:
          Array.isArray(
            data.market_analysis?.market_risks
          )
            ? data.market_analysis.market_risks
            : [],

        researchGaps:
          Array.isArray(
            data.market_analysis?.research_gaps
          )
            ? data.market_analysis.research_gaps
            : [],

        researchAvailable:
          data.market_analysis?.research_available ?? false
      },


      // ==================================================
      // MARKET SCORES
      // ==================================================

      marketScores: {

        demand:
          Number(
            data.market_scores?.demand || 0
          ),

        growth:
          Number(
            data.market_scores?.growth || 0
          ),

        attractiveness:
          Number(
            data.market_scores?.attractiveness || 0
          ),

        overall:
          Number(
            data.market_scores?.overall || 0
          )
      },


      // ==================================================
      // COMPETITOR ANALYSIS
      // ==================================================

      competitorAnalysis: {


        // ----------------------------------------------
        // 1. COMPETITION OVERVIEW
        // ----------------------------------------------

        competitionOverview: {

          competitionLevel:
            data.competitor_analysis
              ?.competition_overview
              ?.competition_level || "",

          summary:
            data.competitor_analysis
              ?.competition_overview
              ?.summary || ""
        },


        // ----------------------------------------------
        // 2. COMPETITORS
        // ----------------------------------------------

        competitors:

          Array.isArray(
            data.competitor_analysis?.competitors
          )

            ? data.competitor_analysis
                .competitors
                .map(competitor => ({

                  name:
                    competitor.name || "",

                  website:
                    competitor.website || "",

                  type:
                    competitor.type || "",

                  targetAudience:
                    competitor.target_audience || "",

                  mainSolution:
                    competitor.main_solution || "",

                  keyFeatures:
                    Array.isArray(
                      competitor.key_features
                    )
                      ? competitor.key_features
                      : [],

                  pricing:
                    competitor.pricing || "",

                  strengths:
                    Array.isArray(
                      competitor.strengths
                    )
                      ? competitor.strengths
                      : [],

                  weaknesses:
                    Array.isArray(
                      competitor.weaknesses
                    )
                      ? competitor.weaknesses
                      : [],

                  threatLevel:
                    competitor.threat_level || ""

                }))

            : [],


        // ----------------------------------------------
        // 3. COMPETITIVE COMPARISON
        // ----------------------------------------------

        competitiveComparison: {

          startupAdvantages:
            Array.isArray(
              data.competitor_analysis
                ?.competitive_comparison
                ?.startup_advantages
            )

              ? data.competitor_analysis
                  .competitive_comparison
                  .startup_advantages

              : [],


          competitorAdvantages:
            Array.isArray(
              data.competitor_analysis
                ?.competitive_comparison
                ?.competitor_advantages
            )

              ? data.competitor_analysis
                  .competitive_comparison
                  .competitor_advantages

              : [],


          startupDisadvantages:
            Array.isArray(
              data.competitor_analysis
                ?.competitive_comparison
                ?.startup_disadvantages
            )

              ? data.competitor_analysis
                  .competitive_comparison
                  .startup_disadvantages

              : [],


          competitorDisadvantages:
            data.competitor_analysis
              ?.competitive_comparison
              ?.competitor_disadvantages || "",


          comparisonSummary:
            data.competitor_analysis
              ?.competitive_comparison
              ?.comparison_summary || ""
        },


        // ----------------------------------------------
        // 4. COMPETITIVE GAPS
        // ----------------------------------------------

        competitiveGaps:

          Array.isArray(
            data.competitor_analysis
              ?.competitive_gaps
          )

            ? data.competitor_analysis
                .competitive_gaps

            : [],


        // ----------------------------------------------
        // 5. BIGGEST COMPETITOR
        // ----------------------------------------------

        biggestCompetitor: {

          name:
            data.competitor_analysis
              ?.biggest_competitor
              ?.name || "",

          reason:
            data.competitor_analysis
              ?.biggest_competitor
              ?.reason || "",

          mainAdvantage:
            data.competitor_analysis
              ?.biggest_competitor
              ?.main_advantage || "",

          threat:
            data.competitor_analysis
              ?.biggest_competitor
              ?.threat || ""
        },


        // ----------------------------------------------
        // 6. STARTUP POSITION
        // ----------------------------------------------

        startupPosition: {

          differentiationLevel:
            data.competitor_analysis
              ?.startup_position
              ?.differentiation_level || "",

          competitiveThreat:
            data.competitor_analysis
              ?.startup_position
              ?.competitive_threat || "",

          startupAdvantages:
            Array.isArray(
              data.competitor_analysis
                ?.startup_position
                ?.startup_advantages
            )

              ? data.competitor_analysis
                  .startup_position
                  .startup_advantages

              : [],


          startupDisadvantages:
            Array.isArray(
              data.competitor_analysis
                ?.startup_position
                ?.startup_disadvantages
            )

              ? data.competitor_analysis
                  .startup_position
                  .startup_disadvantages

              : [],


          biggestCompetitiveRisk:
            data.competitor_analysis
              ?.startup_position
              ?.biggest_competitive_risk || "",

          biggestOpportunity:
            data.competitor_analysis
              ?.startup_position
              ?.biggest_opportunity || ""
        },


        // ----------------------------------------------
        // 7. FINAL COMPETITIVE VERDICT
        // ----------------------------------------------

        finalCompetitiveVerdict:
          data.competitor_analysis
            ?.final_competitive_verdict || ""

      },


      // ==================================================
      // GENERAL ANALYSIS
      // ==================================================

      strengths:
        Array.isArray(data.strengths)
          ? data.strengths
          : [],

      weaknesses:
        Array.isArray(data.weaknesses)
          ? data.weaknesses
          : [],

      assumptions:
        Array.isArray(data.assumptions)
          ? data.assumptions
          : [],

      questions:
        Array.isArray(data.key_questions)
          ? data.key_questions
          : [],


      // ==================================================
      // FINAL EVALUATION
      // ==================================================

      overallIdeaScore:
        Number(
          data.overall_idea_score || 0
        ),

      finalRecommendation:
        data.final_recommendation || "",

      verdict:
        data.verdict || "",

      verdictReason:
        data.verdict_reason || ""

    }
  });
}


// ==================================================
// RETURN RESULTS
// ==================================================

return results;

