=<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Competitor Analysis Report</title>

<style>
  body {
    margin: 0;
    padding: 0;
    background: #f5f7fb;
    font-family: 'Segoe UI', Tahoma, Arial, sans-serif;
    color: #172033;
    direction: rtl;
    text-align: right;
  }
  .wrapper { width: 100%; padding: 35px 15px; }
  .container { max-width: 760px; margin: auto; background: #ffffff; border-radius: 18px; overflow: hidden; border: 1px solid #e7eaf0; }
  .header { padding: 32px; background: #111827; color: #ffffff; }
  .brand { font-size: 13px; font-weight: bold; letter-spacing: 1px; opacity: 0.7; }
  .header h1 { margin: 12px 0 8px; font-size: 28px; }
  .header p { margin: 0; color: #cbd5e1; font-size: 14px; }
  .idea-box { margin: 25px 32px 0; padding: 20px; background: #f8fafc; border: 1px solid #e5e7eb; border-radius: 14px; }
  .idea-label { font-size: 12px; color: #64748b; font-weight: bold; }
  .idea-name { margin-top: 6px; font-size: 21px; font-weight: bold; color: #111827; }
  .content { padding: 32px; }
  .section { margin-bottom: 32px; }
  .section-title { font-size: 18px; font-weight: bold; color: #111827; margin-bottom: 14px; }
  .card { padding: 22px; border-radius: 15px; background: #f8fafc; border: 1px solid #e5e7eb; }
  .bullet-list { list-style: none; padding: 0; margin: 0; }
  .bullet-list li { position: relative; padding-right: 22px; margin-bottom: 10px; font-size: 14px; line-height: 1.7; color: #334155; }
  .bullet-list li:last-child { margin-bottom: 0; }
  .bullet-list li::before { content: "•"; position: absolute; right: 0; color: #4f46e5; font-weight: bold; font-size: 18px; }
  .verdict { padding: 25px; border-radius: 15px; background: #111827; color: #ffffff; font-size: 15px; line-height: 1.8; }
  .verdict-list { list-style: none; padding: 0; margin: 0; }
  .verdict-list li { position: relative; padding-right: 22px; margin-bottom: 10px; font-size: 14px; line-height: 1.7; color: #e2e8f0; }
  .verdict-list li:last-child { margin-bottom: 0; }
  .verdict-list li::before { content: "•"; position: absolute; right: 0; color: #818cf8; font-weight: bold; font-size: 18px; }
  .footer { padding: 24px 32px; border-top: 1px solid #e5e7eb; background: #fafafa; text-align: center; color: #94a3b8; font-size: 11px; }
</style>
</head>

<body>
<div class="wrapper">
  <div class="container">

    <div class="header">
      <div class="brand">STARTUP IDEA REVIEW</div>
      <h1>تقرير تحليل المنافسين</h1>
      <p>دراسة المشهد التنافسي والفرص المتاحة</p>
    </div>

    <div class="idea-box">
      <div class="idea-label">فكرة المشروع</div>
      <div class="idea-name">{{ $('Append row in sheet6').item.json['Idea Name'] || "تحليل الفكرة" }}</div>
    </div>

    <div class="content">

      <!-- 1. COMPETITION OVERVIEW -->
      <div class="section">
        <div class="section-title">١. نظرة عامة على المنافسة</div>
        <div class="card">
          <ul class="bullet-list">
            {{ ($('Append row in sheet6').item.json['Competition Overview'] || '').split('\n').map(i => i.replace(/^[\s•\-\*]+/, '').trim()).filter(Boolean).map(i => '<li>' + i + '</li>').join('') || '<li>غير محدد</li>' }}
          </ul>
        </div>
      </div>

      <!-- 2. COMPETITORS -->
      <div class="section">
        <div class="section-title">٢. المنافسون</div>
        <div class="card">
          <ul class="bullet-list">
            {{ ($('Append row in sheet6').item.json['Competitors'] || '').split('\n').map(i => i.replace(/^[\s•\-\*]+/, '').trim()).filter(Boolean).map(i => '<li>' + i + '</li>').join('') || '<li>غير محدد</li>' }}
          </ul>
        </div>
      </div>

      <!-- 3. COMPETITIVE COMPARISON -->
      <div class="section">
        <div class="section-title">٣. المقارنة التنافسية</div>
        <div class="card">
          <ul class="bullet-list">
            {{ ($('Append row in sheet6').item.json['Competitive Comparison'] || '').split('\n').map(i => i.replace(/^[\s•\-\*]+/, '').trim()).filter(Boolean).map(i => '<li>' + i + '</li>').join('') || '<li>غير محدد</li>' }}
          </ul>
        </div>
      </div>

      <!-- 4. COMPETITIVE GAPS -->
      <div class="section">
        <div class="section-title">٤. الفجوات التنافسية</div>
        <div class="card">
          <ul class="bullet-list">
            {{ ($('Append row in sheet6').item.json['Competitive Gaps'] || '').split('\n').map(i => i.replace(/^[\s•\-\*]+/, '').trim()).filter(Boolean).map(i => '<li>' + i + '</li>').join('') || '<li>غير محدد</li>' }}
          </ul>
        </div>
      </div>

      <!-- 5. BIGGEST COMPETITOR -->
      <div class="section">
        <div class="section-title">٥. أكبر منافس</div>
        <div class="card">
          <ul class="bullet-list">
            {{ ($('Append row in sheet6').item.json['Biggest Competitor'] || '').split('\n').map(i => i.replace(/^[\s•\-\*]+/, '').trim()).filter(Boolean).map(i => '<li>' + i + '</li>').join('') || '<li>غير محدد</li>' }}
          </ul>
        </div>
      </div>

      <!-- 6. STARTUP POSITION -->
      <div class="section">
        <div class="section-title">٦. الموقع التنافسي للمشروع</div>
        <div class="card">
          <ul class="bullet-list">
            {{ ($('Append row in sheet6').item.json['Startup Position'] || '').split('\n').map(i => i.replace(/^[\s•\-\*]+/, '').trim()).filter(Boolean).map(i => '<li>' + i + '</li>').join('') || '<li>غير محدد</li>' }}
          </ul>
        </div>
      </div>

      <!-- 7. FINAL COMPETITIVE VERDICT -->
      <div class="section">
        <div class="section-title">٧. الحكم التنافسي النهائي</div>
        <div class="verdict">
          <ul class="verdict-list">
            {{ ($('Append row in sheet6').item.json['Final Competitive Verdict'] || '').split('\n').map(i => i.replace(/^[\s•\-\*]+/, '').trim()).filter(Boolean).map(i => '<li>' + i + '</li>').join('') || '<li>لا يوجد حكم تنافسي نهائي.</li>' }}
          </ul>
        </div>
      </div>

    </div>

    <div class="footer">
      Generated by Startup Idea Review <br> Competitor Analysis Report
    </div>

  </div>
</div>
</body>
</html>
